Rules.InvariantScript:
Set(varIsNewSetup, IsBlank(varEditSetup.'Id (ID)'));
// Preload the responsible person from the existing record, so editing any
// other field does not silently clear it.
Set(
    varSetupHolder,
    {
        DisplayName: Coalesce(varEditSetup.ResponsiblePerson.DisplayName, ""),
        Mail: Coalesce(varEditSetup.ResponsiblePerson.Email, "")
    }
)

Set(
    varSetupHolder,
    { DisplayName: ThisItem.DisplayName, Mail: ThisItem.Mail }
);
Reset(txtSetupPersonSearch)

// Patch gets a literal record in each branch. Handing it a record bound
// with With() fails as "expecting a Record value, but of a different schema",
// and putting the If around Defaults() and an existing record instead unions
// two record types.
Set(
    varSavedSetup,
    If(
        varIsNewSetup,
        Patch(
            Equipment_Setups,
            Defaults(Equipment_Setups),
            {
            Titel:           Trim(txtSetupId.Text),
            SetupName:       Trim(txtSetupName.Text),
            CurrentCampus:   { Value: drpSetupCampus.Selected.Value },
            CurrentLocation: { Value: drpSetupRoom.Selected.Value },
            Status:          { Value: drpSetupStatus.Selected.Value },
            Description:     Trim(txtSetupDesc.Text)
            }
        ),
        Patch(
            Equipment_Setups,
            // LookUp by ID, not the variable itself: a record carried in a global
            // variable loses its schema, and Patch rejects it as "a Record value,
            // but of a different schema".
            LookUp(Equipment_Setups, 'Id (ID)' = varEditSetup.'Id (ID)'),
            {
            SetupName:       Trim(txtSetupName.Text),
            CurrentCampus:   { Value: drpSetupCampus.Selected.Value },
            CurrentLocation: { Value: drpSetupRoom.Selected.Value },
            Status:          { Value: drpSetupStatus.Selected.Value },
            Description:     Trim(txtSetupDesc.Text)
            }
        )
    )
);

// Person field separately, so an empty pick does not clear the existing value.
If(
    !IsBlank(varSetupHolder.Mail) && !IsBlank(varSavedSetup.'Id (ID)'),
    Patch(
        Equipment_Setups,
        LookUp(Equipment_Setups, 'Id (ID)' = varSavedSetup.'Id (ID)'),
        {
            ResponsiblePerson: {
                '@odata.type': "#Microsoft.Azure.Connectors.SharePoint.SPListExpandedUser",
                Claims: "i:0#.f|membership|" & Lower(varSetupHolder.Mail),
                DisplayName: varSetupHolder.DisplayName,
                Email: varSetupHolder.Mail,
                Department: "",
                JobTitle: "",
                Picture: ""
            }
        }
    )
);

If(
    IsEmpty(Errors(Equipment_Setups)),
    Notify(
        If(varIsNewSetup, "Setup added. Add its assets below.", "Changes saved."),
        NotificationType.Success
    );
    Set(varCurrentSetup, LookUp(Equipment_Setups, 'Id (ID)' = varSavedSetup.'Id (ID)'));
    Set(varEditSetup, Blank());
    Navigate(scr_SetupDetail, ScreenTransition.Fade),
    Notify(
        "Save failed: " & Concat(Errors(Equipment_Setups), Message, " | "),
        NotificationType.Error
    )
)
